import type { LinkComponentProps } from "@canonical/react-ds-global";
import { render, screen } from "@testing-library/react";
import type { ReactElement } from "react";
import { describe, expect, it } from "vitest";
import EntityRow from "./EntityRow.js";

/** A router link stand-in: an anchor that says it came through the router. */
const RouterLink = ({
  href,
  className,
  children,
}: LinkComponentProps): ReactElement => (
  <a className={className} data-router="" href={href}>
    {children}
  </a>
);

/** Render one row in the list it belongs to and return the row. */
function renderRow(row: ReactElement): HTMLElement {
  render(<ul>{row}</ul>);
  return screen.getByRole("listitem");
}

describe("EntityRow", () => {
  describe("title", () => {
    it("renders the title alone, as inert text", () => {
      const row = renderRow(<EntityRow title="Layout" />);
      expect(row.querySelector(".identity")?.children).toHaveLength(1);
      expect(screen.getByText("Layout").tagName).toBe("SPAN");
      expect(row.querySelector(".meta")).toBeNull();
      expect(screen.queryByRole("link")).toBeNull();
    });
  });

  describe("location and meta", () => {
    it("renders the location before the title and the meta at the end", () => {
      const row = renderRow(
        <EntityRow location="ds:" meta="abstract" title="Layout" />,
      );
      expect(
        [...row.querySelectorAll(".location, .title, .meta")].map(
          (element) => element.className,
        ),
      ).toEqual(["location", "title", "meta"]);
      expect(row.querySelector(".identity")?.textContent).toBe("ds:Layout");
      expect(row.lastElementChild?.textContent).toBe("abstract");
    });
  });

  describe("href and LinkComponent", () => {
    it("links the title to the home through an intrinsic anchor by default", () => {
      renderRow(<EntityRow href="#layout" location="ds:" title="Layout" />);
      const link = screen.getByRole("link", { name: "Layout" });
      expect(link.getAttribute("href")).toBe("#layout");
      expect(link.className).toBe("title");
    });

    it("links only the title, through the LinkComponent it is given", () => {
      renderRow(
        <EntityRow
          href="#layout"
          LinkComponent={RouterLink}
          location="ds:"
          meta="abstract"
          title="Layout"
        />,
      );
      const links = screen.getAllByRole("link");
      expect(links).toHaveLength(1);
      expect(links.at(0)?.hasAttribute("data-router")).toBe(true);
    });
  });

  describe("native props", () => {
    it("forwards native props to the root and merges className after its own", () => {
      const row = renderRow(
        <EntityRow className="result" id="layout-row" title="Layout" />,
      );
      expect(row.className).toBe("ds entity-row result");
      expect(row.id).toBe("layout-row");
    });
  });
});
